// ❌ WRONG: treats 0 and "" as missing
function isMissing(x) {
  return !x; // 0 and "" are considered missing!
}

isMissing(0)   // true (WRONG - 0 is a valid value)
isMissing("")  // true (WRONG - empty string might be valid)
isMissing(null) // true (correct)

// ✅ CORRECT patterns:
// For "not provided":
function isNotProvided(x) {
  return x == null; // checks for null or undefined
}

// For empty string:
function isEmpty(x) {
  return typeof x === 'string' && x.trim() === '';
}

// For number validation:
function isValidNumber(x) {
  return Number.isFinite(x);
}

// PATCH /api/users/:id
// undefined → do not change
// null → clear value

const updates = {
  name: 'Alice',      // update to 'Alice'
  email: null,        // clear email
  phone: undefined    // don't change phone
}

// Backend handler:
function applyPatch(existing, updates) {
  const result = { ...existing }

  for (const [key, value] of Object.entries(updates)) {
    if (value === undefined) {
      // Skip - don't change
      continue
    }
    if (value === null) {
      // Clear the field
      result[key] = null
    } else {
      // Update the field
      result[key] = value
    }
  }

  return result
}

