// ✅ Safe parsing
function parseNumber(str) {
  const num = Number(str)
  return Number.isFinite(num) ? num : null
}

// ✅ Normalize input at boundary
function normalizeInput(str) {
  return str
    .trim()                    // remove whitespace
    .toLowerCase()             // consistent casing
    .normalize('NFC')          // Unicode normalization
}

// ✅ Email uniqueness
function normalizeEmail(email) {
  return email.trim().toLowerCase()
}

// ✅ Search keys
function normalizeSearchKey(str) {
  return str
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ')      // normalize whitespace
}

// ❌ Mutating request DTO, then logging it later
function processRequest(req) {
  logger.info('Request received', { req })

  // Enrich request
  req.userId = extractUserId(req)
  req.timestamp = Date.now()

  // Later logging shows mutated data!
  // Logs lie about what was actually received

  return handleRequest(req)
}

// ✅ Clone before mutate, or compute derived object
function processRequest(req) {
  logger.info('Request received', { req })

  // Create enriched version
  const enrichedReq = {
    ...req,
    userId: extractUserId(req),
    timestamp: Date.now()
  }

  return handleRequest(enrichedReq)
}

// ✅ Private mutation is OK if it doesn't escape
function buildConfig() {
  const config = {}  // local, doesn't escape

  config.env = process.env.NODE_ENV
  config.port = parseInt(process.env.PORT)

  return Object.freeze(config)  // freeze before returning
}

// ❌ TypeScript can't validate external data
interface User {
  id: number
  email: string
}

// This compiles fine but crashes at runtime!
const response = await fetch('/api/user')
const user: User = await response.json()
// What if API returns { id: '123', email: null }?
// TypeScript won't catch this!

console.log(user.email.toLowerCase())  // 💥 Runtime error!

// ✅ Use runtime validation library
import { z } from 'zod'

const UserSchema = z.object({
  id: z.number(),
  email: z.string().email()
})

type User = z.infer<typeof UserSchema>

// Validate at API boundary
const response = await fetch('/api/user')
const data = await response.json()
const user = UserSchema.parse(data)  // throws if invalid

// Now TypeScript AND runtime are aligned
console.log(user.email.toLowerCase())  // ✅ Safe!
